async def _read_views(self, views):
    """Capture only tabs selected from one observed document; never discover routes."""
    base = self.site.last_observation
    url = self.site.page.url
    jobs, messages = [], []
    try:
        for view in views:
            current = await self.site.observe()
            mapped = self.site.rematch({'ref': view['ref']}, base, current)
            if isinstance(mapped, str):
                messages.append('ERROR: ' + mapped)
                break
            _, element = await self.site._element(mapped['ref'])
            if await element.get_attribute('role') != 'tab':
                messages.append('ERROR: selected control is not a semantic tab; use separate observed actions')
                break
            result = await self.site.act('click', {'ref': mapped['ref']})
            if result.startswith('ERROR') or self.site.page.url != url:
                messages.append('ERROR: tab action failed or changed document; inspect current page')
                break
            text = await self.site.full_text()
            jobs.append(asyncio.create_task(self._selected_extract(view['kind'], text, url, via='page')))
        if jobs:
            messages.extend(await asyncio.gather(*jobs))
        return '\n'.join(messages) or 'ERROR: select at least one observed tab'
    finally:
        for job in jobs:
            if not job.done():
                job.cancel()
        if jobs:
            await asyncio.gather(*jobs, return_exceptions=True)

# ---------------------------------------------------------------- background extraction
async def _extraction(self, label: str, work) -> str:
    """Run an extraction now, or (background_extraction) start it and let the model continue navigating."""
    if not self.mission.background_extraction:
        return await work
    label = f"[x{len(self.history) + 1}] {label}"
    self.pending[label] = asyncio.ensure_future(work)
    metrics.mission(self.tag)["background"] += 1
    return (f"extraction started in the background: {label}. Its result and the updated checklist arrive in a "
            f"later step; continue with the next page meanwhile (do not request it again).")

